begin;
create extension if not exists pgtap with schema extensions;
select plan(28);
select public.register_relay('00000000-0000-4000-8000-0000000000d1', 'google-contact-admin', '[Admin]');
select public.register_relay('00000000-0000-4000-8000-0000000000a1', 'google-contact-relais', '[Relais]');
insert into prive.admins(id) values ('00000000-0000-4000-8000-0000000000d1');
insert into public.institutions(id, name, kind) values ('61000000-0000-4000-8000-000000000001', '[École contact public]', 'privee');
insert into public.campuses(id, institution_id, slug, division_id, origin, publication)
select '62000000-0000-4000-8000-000000000001', '61000000-0000-4000-8000-000000000001', 'ecole-contact-public', id, 'admin', 'brouillon' from public.geo_divisions where level = 3 limit 1;

insert into public.field_submissions(id, relay_id, taken_at, sign_name) values ('63000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000a1', now(), '[Contact privé]');
insert into prive.direction_contacts(id, submission_id, role, whatsapp, contact_agreement) values ('64000000-0000-4000-8000-000000000001', '63000000-0000-4000-8000-000000000001', 'directeur', '242060000008', true);

set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-4000-8000-0000000000a1","role":"authenticated"}', true);
select throws_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000001', '242060000001', current_date, 'directeur', 'appel')$$, '42501', null, 'Un relais ne publie pas de contact');
select throws_ok($$select * from prive.public_contact_agreements$$, '42501', null, 'La preuve reste privée pour le relais');
reset role;
set local role anon;
select throws_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000001', null, null, null, null)$$, '42501', null, 'Un visiteur ne retire pas de contact');
select throws_ok($$select * from prive.public_contact_agreements$$, '42501', null, 'La preuve reste privée pour le visiteur');
reset role;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-4000-8000-0000000000d1","role":"authenticated"}', true);
select throws_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000001', '242060000001', null, 'directeur', 'appel')$$, '22023', null, 'Pas de numéro sans date de publication autorisée');
select throws_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000001', '242060000001', current_date + 2, 'directeur', 'appel')$$, '22023', null, 'Pas de date future');
select throws_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000001', '242060000001', current_date, null, 'appel')$$, '22023', null, 'Fonction obligatoire');
select throws_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000001', '242060000001', current_date, 'directeur', null)$$, '22023', null, 'Canal obligatoire');
select throws_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000001', '2420060000001', current_date, 'directeur', 'appel')$$, '22023', null, 'Numéro congolais suspect refusé');
select throws_ok($$update public.campuses set public_phone = '242060000001', public_phone_agreed_on = current_date where id = '62000000-0000-4000-8000-000000000001'$$, '42501', null, 'L’API ne contourne pas la commande par UPDATE');
select lives_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000001', '242060000001', current_date, 'directeur', 'appel')$$, 'Accord explicite enregistré');
select is((select public_phone::text from public.campuses where id = '62000000-0000-4000-8000-000000000001'), '242060000001', 'Le numéro est enregistré');
select is((select publication::text from public.campuses where id = '62000000-0000-4000-8000-000000000001'), 'brouillon', 'Aucune publication automatique');
select is((select verification_state::text from public.campuses where id = '62000000-0000-4000-8000-000000000001'), 'relevee', 'Aucun badge créé');
reset role;
set local role anon;
select is((select count(*)::int from public.public_campuses where id = '62000000-0000-4000-8000-000000000001'), 0, 'Contact d’un brouillon invisible au public');
reset role;
update public.campuses set publication = 'publiee' where id = '62000000-0000-4000-8000-000000000001';
set local role anon;
select is((select public_phone::text from public.public_campuses where id = '62000000-0000-4000-8000-000000000001'), '242060000001', 'Le public lit le contact de l’école publiée');
select is((select public_phone_agreed_on from public.public_campuses where id = '62000000-0000-4000-8000-000000000001'), current_date, 'La date accompagne le numéro public');
reset role;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-4000-8000-0000000000d1","role":"authenticated"}', true);
select lives_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000001', '242060000002', current_date, 'promoteur', 'whatsapp')$$, 'Modification avec nouvel accord');
select lives_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000001', null, null, null, null)$$, 'Retrait explicite');
select throws_ok($$select public.set_school_public_contact('62000000-0000-4000-8000-000000000099', null, null, null, null)$$, 'P0002', null, 'École inconnue refusée');
reset role;
set local role anon;
select is((select public_phone::text from public.public_campuses where id = '62000000-0000-4000-8000-000000000001'), null, 'Le numéro retiré n’est plus dans le catalogue');
select is((select public_phone_agreed_on from public.public_campuses where id = '62000000-0000-4000-8000-000000000001'), null, 'La date publique est retirée aussi');
reset role;
select is((select count(*)::int from prive.public_contact_agreements where campus_id = '62000000-0000-4000-8000-000000000001'), 3, 'Ajout, modification et retrait sont tracés en privé');
select is((select whatsapp::text from prive.direction_contacts where id = '64000000-0000-4000-8000-000000000001'), '242060000008', 'Le numéro privé reste inchangé après le retrait public');
select is((select count(*)::int from prive.direction_contacts), 1, 'Aucune copie supplémentaire du contact privé');
select is((select sign_phone::text from public.campuses where id = '62000000-0000-4000-8000-000000000001'), null, 'Le numéro d’enseigne ne change pas');
select is((select count(*)::int from prive.public_contact_agreements where recorded_by <> '00000000-0000-4000-8000-0000000000d1'), 0, 'La preuve indique le compte administrateur');
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-4000-8000-0000000000d1","role":"authenticated"}', true);
select throws_ok($$insert into public.campuses(institution_id, slug, origin, public_phone, public_phone_agreed_on) values ('61000000-0000-4000-8000-000000000001', 'contournement-insert', 'admin', '242060000001', current_date)$$, '42501', null, 'INSERT ne contourne pas non plus la preuve');
reset role;
select * from finish();
rollback;
